CREATE TABLE `bbs_category` (
  `category_id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `category_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '分类描述',
  `icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '分类图标',
  `sort_order` int DEFAULT '0' COMMENT '显示顺序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `post_count` int DEFAULT '0' COMMENT '帖子数量',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='论坛分类表';

INSERT INTO `bbs_category` (`category_id`, `category_name`, `category_desc`, `icon`, `sort_order`, `status`, `post_count`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1, '通用社区', '覆盖全场景通用事务，聚焦跨板块协作、基础问题解决与全员信息同步，是企业全域沟通枢纽。\n', 'el-icon-cpu', 1, '0', 164, 'admin', '2026-02-03 14:21:23', '', NULL, ''), (2, '产品社区', '围绕产品全生命周期，汇聚需求研讨、研发协同、迭代优化与产品问题攻坚的产品相关人员。\n', 'el-icon-s-promotion', 2, '0', 1, 'admin', '2026-02-03 14:21:23', '', NULL, ''), (3, '网络社区', '聚焦网络架构、运维保障、故障排查与安全防护，是技术团队处理网络相关事务的交流平台。\n', 'el-icon-document', 3, '0', 2, 'admin', '2026-02-03 14:21:23', '', NULL, ''), (4, '人力社区', '专注人力资源全模块，涵盖招聘、薪酬、员工关系、培训发展，服务企业人力管理与员工咨询。\n', 'el-icon-sunny', 4, '0', 2, 'admin', '2026-02-03 14:21:23', '', NULL, ''), (5, '财务社区', '围绕企业财务工作，开展账务处理、预算管控、报销审核、税务筹划的财务人员专属交流阵地。\n\n\n\n\n\n\n\n每个社区的具体功能有哪些？\n如何加入这些社区？\n这些社区之间有什么联系和区别？\n', 'el-icon-question', 5, '0', 2, 'admin', '2026-02-03 14:21:23', '', NULL, '');

CREATE TABLE `bbs_checkin` (
  `checkin_id` bigint NOT NULL AUTO_INCREMENT COMMENT '签到ID',
  `user_id` varchar(64) NOT NULL COMMENT '用户ID',
  `checkin_date` date NOT NULL COMMENT '签到日期',
  `streak` int NOT NULL DEFAULT '1' COMMENT '连续签到天数',
  `points_earned` int NOT NULL DEFAULT '2' COMMENT '本次获得积分',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`checkin_id`),
  UNIQUE KEY `uk_user_date` (`user_id`,`checkin_date`),
  KEY `idx_checkin_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户每日签到记录';

