  KEY `idx_collect_topic_content_activity` (`activity_id`),
  KEY `idx_collect_topic_content_score` (`score`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Topic activity linked content';

