:49', 'PUBLICIZED', 'system', '系统', NULL), (23, 4, '投稿成功', '提案已提交，进入初审队列', 10, '2026-05-04 22:11:26', 'PENDING_L1', '2', '张三', NULL), (24, 4, '初审全部通过', '测试', 35, '2026-05-04 22:19:14', 'L1_PASSED', '1', '管理员', NULL), (25, 4, '复审全部通过', '复审', 55, '2026-05-04 22:19:27', 'L2_PASSED', '1', '管理员', NULL), (26, 4, '终审全部通过并立项', '终审通过，请按时完成项目落地', 70, '2026-05-04 22:19:46', 'APPROVED', '1', '管理员', NULL), (27, 4, '推进中', '进度更新 ，完成研发', 60, '2026-05-04 22:28:03', 'IMPLEMENTING', '2', '张三', NULL), (28, 4, '推进中', '进度更新 ，完成研发', 100, '2026-05-04 22:28:16', 'LANDED', '2', '张三', NULL), (29, 4, '成果公示', '本次《基于 AI 大模型的智能客服意图识别优化方案》已完成全量上线，达成预期业务目标，成果总结如下：\n降本增效成果\n人工客服承接量降低 35%，单月减少约 12 万次人工进线，人力运营成本压降 28%；用户问题一次性解决率提升至 92%，平均对话时长缩短 42%，客服工单处理效率提升 38%。\n用户体验成果\n用户服务满意度提升 21 个百分点，NPS 提升 12 分，投诉率下降 45%；7×24 小时自助服务覆盖实现 100%，夜间用户响应率从 27% 提升至 100%，夜间服务工单占比下降 63%，用户流失率降低 6%。\n业务沉淀成果\n沉淀高质量客服对话语料 120 万条，输出产品优化需求 8 项，已落地高频问题优化、自助服务流程简化等 5 项改进；形成可复用的 AI 客服解决方案，成功复制至 2 条业务线，累计节省系统建设成本约 40 万元。\n风险合规成果\n通过标准化话术与风险识别能力，违规话术发生率降至 0，合规投诉降为 0，有效规避了潜在监管风险与声誉损失。', 100, '2026-05-04 22:28:44', 'PUBLICIZED', 'system', '系统', NULL), (33, 10, '投稿成功', '提案已提交，进入初审队列', 10, '2026-05-22 04:05:53', 'PENDING_L1', '2', '张三', NULL), (34, 11, '投稿成功', '提案已提交，进入初审队列', 10, '2026-05-22 04:05:53', 'PENDING_L1', '2', '张三', NULL), (35, 11, '初审全部通过', '初审通过：方向合理。', 35, '2026-05-22 04:05:53', 'L1_PASSED', 'l1reviewer', '初审员', NULL), (36, 11, '复审全部通过', '复审通过：方案可执行。', 55, '2026-05-22 04:05:54', 'L2_PASSED', 'l2reviewer', '复审员', NULL), (37, 11, '终审全部通过并立项', '终审通过：同意立项推进。', 70, '2026-05-22 04:05:54', 'APPROVED', 'l3reviewer', '终审员', NULL), (38, 13, '投稿成功', '提案已提交，进入初审队列', 10, '2026-05-22 04:10:00', 'PENDING_L1', '2', '张三', NULL), (39, 14, '投稿成功', '提案已提交，进入初审队列', 10, '2026-05-22 04:10:00', 'PENDING_L1', '2', '张三', NULL), (40, 14, '初审全部通过', '初审通过：方向合理。', 35, '2026-05-22 04:10:00', 'L1_PASSED', 'l1reviewer', '初审员', NULL), (41, 14, '复审全部通过', '复审通过：方案可执行。', 55, '2026-05-22 04:10:01', 'L2_PASSED', 'l2reviewer', '复审员', NULL), (42, 14, '终审全部通过并