CREATE TABLE `bbs_idea_proposal` (
  `idea_id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `content` text NOT NULL,
  `biz_value` varchar(2000) DEFAULT NULL COMMENT '业务价值',
  `status` varchar(20) NOT NULL DEFAULT 'reviewing' COMMENT 'reviewing/executing/done/publicized/rejected',
  `avg_score` decimal(5,2) NOT NULL DEFAULT '0.00',
  `result_summary` text,
  `submit_user_id` varchar(64) NOT NULL,
  `submit_nick_name` varchar(100) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `category` varchar(50) DEFAULT 'other' COMMENT '提案分类(product/tech/manage/cost/other)',
  `background_text` text COMMENT '提案背景',
  `plan_text` longtext COMMENT '实施方案',
  `expected_value` text COMMENT '预期价值',
  `visibility_scope` varchar(20) DEFAULT 'review_group' COMMENT '可见范围(all/review_group/admin)',
  `attachment_urls` text COMMENT '附件URL，逗号分隔',
  `related_case` text COMMENT '相关案例',
  `team_name` varchar(100) DEFAULT NULL COMMENT '提案人团队',
  `is_draft` char(1) DEFAULT '0' COMMENT '是否草稿(0否1是)',
  `review_stage` varchar(20) DEFAULT 'L1' COMMENT '当前评审环节(L1/L2/L3/NONE)',
  `reject_reason` varchar(1000) DEFAULT NULL COMMENT '驳回原因',
  `project_time` datetime DEFAULT NULL COMMENT '立项时间',
  `landing_time` datetime DEFAULT NULL COMMENT '落地时间',
  `is_publicized` char(1) DEFAULT '0' COMMENT '是否公示(0否1是)',
  `incentive_points` int DEFAULT '0' COMMENT '创新激励积分',
  `honor_badge` varchar(100) DEFAULT NULL COMMENT '荣誉勋章',
  `like_count` int DEFAULT '0' COMMENT '公示墙点赞数',
  `share_count` int DEFAULT '0' COMMENT '公示墙分享数',
  `review_deadline` datetime DEFAULT NULL COMMENT '当前环节评审截止时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标识(0存在2删除)',
  PRIMARY KEY (`idea_id`),
  KEY `idx_idea_status` (`status`),
  KEY `idx_idea_user` (`submit_user_id`),
  KEY `idx_idea_category` (`category`),
  KEY `idx_idea_publicized` (`is_publicized`),
  KEY `idx_idea_stage` (`review_stage`),
  KEY `idx_idea_deadline` (`review_deadline`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Innovation proposals';

