CREATE TABLE `bbs_qa_question` (
  `question_id` bigint NOT NULL AUTO_INCREMENT COMMENT '问题ID',
  `title` varchar(200) NOT NULL COMMENT '问题标题',
  `content` longtext NOT NULL COMMENT '问题内容（富文本）',
  `category` varchar(50) NOT NULL DEFAULT 'tech' COMMENT '分类：tech技术/product产品/hr人事/admin行政/other其他',
  `reward_points` int NOT NULL DEFAULT '10' COMMENT '悬赏积分（提交时冻结）',
  `frozen_points` int NOT NULL DEFAULT '0' COMMENT '已冻结积分',
  `status` varchar(20) NOT NULL DEFAULT 'open' COMMENT '状态：open待解答/solved已解决/archived已归档/cancelled已撤销',
  `best_answer_id` bigint DEFAULT NULL COMMENT '最佳答案ID',
  `ask_user_id` varchar(64) NOT NULL COMMENT '提问者用户ID',
  `ask_nick_name` varchar(100) DEFAULT NULL COMMENT '提问者昵称',
  `ask_avatar` varchar(500) DEFAULT NULL COMMENT '提问者头像',
  `ask_dept_name` varchar(100) DEFAULT NULL COMMENT '提问者部门',
  `visibility_scope` varchar(20) NOT NULL DEFAULT 'all' COMMENT '可见范围：all全员/dept部门/specific指定人员',
  `visibility_extra` varchar(500) DEFAULT NULL COMMENT '可见范围额外数据（部门ID/用户ID列表）',
  `expiry_time` datetime DEFAULT NULL COMMENT '问题有效期',
  `close_time` datetime DEFAULT NULL COMMENT '关闭/解决时间',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览数',
  `answer_count` int NOT NULL DEFAULT '0' COMMENT '回答数',
  `audit_status` varchar(20) NOT NULL DEFAULT 'approved' COMMENT '审核状态：pending待审核/approved已通过/rejected已拒绝',
  `audit_reason` varchar(500) DEFAULT NULL COMMENT '审核不通过原因',
  `tags` varchar(500) DEFAULT NULL COMMENT '关键词标签（逗号分隔）',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`question_id`),
  KEY `idx_status` (`status`),
  KEY `idx_category` (`category`),
  KEY `idx_ask_user_id` (`ask_user_id`),
  KEY `idx_audit_status` (`audit_status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业问答-问题表';

INSERT INTO `bbs_qa_question` (`question_id`, `title`, `content`, `category`, `reward_points`, `frozen_points`, `status`, `best_answer_id`, `ask_user_id`, `ask_nick_name`, `ask_avatar`, `ask_dept_name`, `visibility_scope`, `visibility_extra`, `expiry_time`, `close_time`, `archive_time`, `view_count`, `answer_count`, `audit_status`, `audit_reason`, `tags`, `del_flag`, `create_by`, `update_by`, `create_time`, `update_time`, `remark`) VALUES (1, '悬赏提问测试001', '现在的AI到底能做什么？', 'tech', 10, 10, 'archived', 1, '1', '管理员', NULL, NULL, 'dept', NULL, '2026-05-29 00:00:00', '2026-05-01 21:24:06', '2026-05-01 21:24:35', 24, 3, 'approved', NULL, '测试,AI', '0', '1', NULL, '2026-05-01 21:07:44', '2026-10-18 09:10:32', NULL), (2, '1231312', '12312312313123123123132231', 'tech', 20, 20, 'solved', 7, '2', '张三', NULL, NULL, 'all', NULL, '2026-05-25 00:00:00', '2026-10-18 09:11:37', NULL, 8, 2, 'approved', NULL, '123', '0', '2', NULL, '2026-05-22 03:16:44', '2026-10-18 09:11:37', NULL), (3, '你知道明天天气怎么样么', '你知道明天天气怎么样么', 'other', 40, 40, 'archived', 4, '2', '张三', NULL, '研发部门', 'all', NULL, '2026-10-19 00:00:00', '2026-10-18 09:10:10', '2026-10-18 09:10:17', 10, 3, 'approved', NULL, '天气', '0', '2', NULL, '2026-10-18 09:02:00', '2026-10-18 09:10:17', NULL);

CREATE TABLE `bbs_sensitive_word` (
  `word_id` bigint NOT NULL AUTO_INCREMENT COMMENT '敏感词ID',
  `word` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '敏感词内容',
  `word_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '5' COMMENT '敏感词类型（1政治敏感 2色情低俗 3暴力血腥 4广告营销 5其他）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`word_id`) USING BTREE,
  KEY `idx_word` (`word`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=135 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='敏感词表';

