  `tag_id` bigint NOT NULL COMMENT '标签ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '订阅时间',
  PRIMARY KEY (`follow_id`),
  UNIQUE KEY `uk_user_tag` (`user_id`,`tag_id`),
